const { seg, eo, ei, lerp } = kit;

kit.scene('mobile-drawer', {
  init(kit) {
    const lockupUrl = W.logoLockupUrl(kit);
    kit.stage.append(kit.h(
      '<div class="ground">' +
      W.studyChrome('3 · Mobile Overlay Drawer', '390px phone viewport', 'Same-coordinate open/close trigger · No content shift') +
      '<div class="ui-window" style="left:410px;top:152px;width:390px;height:800px;border-radius:36px;background:var(--ground)">' +
        '<div style="padding:16px 20px 8px;display:flex;align-items:center;gap:8px">' +
          '<div style="width:44px;height:44px;margin-left:-10px;display:flex;align-items:center;justify-content:center;color:var(--main)">' + W.panelSvg() + '</div>' +
          '<img src="' + lockupUrl + '" alt="Exam App" style="height:26px;width:auto"/>' +
        '</div>' +
        '<div style="padding:4px 20px 14px;border-bottom:1px solid var(--hair);font-size:14px;font-weight:600;color:var(--second)">DATAPREV · 2026 · Analyst (IT)</div>' +
        '<div style="padding:20px;display:flex;flex-direction:column;gap:12px">' +
          '<h2 style="margin:0;font-size:16px;font-weight:600">Question 1</h2>' +
          '<p style="margin:0;font-size:16px;line-height:24px">Which HTTP method is defined as safe and idempotent?</p>' +
          '<div style="padding:10px 12px;border-radius:6px;font-size:16px">A. POST</div>' +
          '<div style="padding:10px 12px;border-radius:6px;background:var(--tint);font-size:16px;font-weight:600">B. GET</div>' +
          '<div style="padding:10px 12px;border-radius:6px;font-size:16px">C. PATCH</div>' +
          '<div style="padding:10px 12px;border-radius:6px;font-size:16px">D. CONNECT</div>' +
          '<div style="margin-top:8px;width:112px;height:44px;border-radius:6px;background:var(--accent);color:var(--on-brand);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:600">Answer</div>' +
        '</div>' +
        '<div class="mobile-drawer-scrim" style="position:absolute;inset:0;background:var(--scrim);opacity:0;pointer-events:none"></div>' +
        '<aside class="mobile-drawer-panel" style="position:absolute;left:0;top:0;bottom:0;width:304px;box-sizing:border-box;background:var(--ground);border-right:1px solid var(--hair);padding:16px 12px;display:flex;flex-direction:column;gap:16px;transform:translateX(-312px)">' +
          '<div style="display:flex;align-items:center;gap:8px;padding-left:8px">' +
            '<div style="width:44px;height:44px;margin-left:-10px;display:flex;align-items:center;justify-content:center;color:var(--main)">' + W.closeSvg() + '</div>' +
            '<img src="' + lockupUrl + '" alt="Exam App" style="height:26px;width:auto"/>' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:8px">' +
            '<div style="padding:12px;border-radius:6px;background:var(--tint);display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:20px;font-weight:600;color:var(--main)">' +
              '<span style="color:var(--accent);margin-top:2px">' + W.docSvg() + '</span>' +
              '<span>DATAPREV · 2026 Analyst (Information Technology)</span>' +
            '</div>' +
            '<div style="padding:12px;border-radius:6px;display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:20px;color:var(--main)">' +
              '<span style="color:var(--second);margin-top:2px">' + W.docSvg() + '</span>' +
              '<span>PPSA · 2025 Analyst (Systems Engineering)</span>' +
            '</div>' +
          '</div>' +
          '<div style="padding:12px;border-radius:6px;background:var(--nav-bg);color:var(--main);font-size:13px;line-height:18px">' +
            'Changing competitions clears answers on this page.' +
          '</div>' +
        '</aside>' +
      '</div>' +
      '<div style="position:absolute;left:890px;top:220px;width:720px;display:flex;flex-direction:column;gap:20px">' +
        '<div class="mobile-drawer-note1" style="padding:24px;border-radius:12px;background:var(--nav-bg)">' +
          '<div style="font-size:22px;font-weight:700;color:var(--main);margin-bottom:8px">Overlay drawer geometry</div>' +
          '<div style="font-size:18px;line-height:26px;color:var(--second)">Drawer width clamps at 304px over a dimmed scrim so underlying question text never reflows.</div>' +
        '</div>' +
        '<div class="mobile-drawer-note2" style="padding:24px;border-radius:12px;background:var(--nav-bg)">' +
          '<div style="font-size:22px;font-weight:700;color:var(--main);margin-bottom:8px">Same-coordinate open and close</div>' +
          '<div style="font-size:18px;line-height:26px;color:var(--second)">Close button sits at the exact top-left target coordinates with a distinct close glyph.</div>' +
        '</div>' +
        '<div class="mobile-drawer-note3" style="padding:24px;border-radius:12px;background:var(--nav-bg)">' +
          '<div style="font-size:22px;font-weight:700;color:var(--main);margin-bottom:8px">Nonmodal answer-loss warning</div>' +
          '<div style="font-size:18px;line-height:26px;color:var(--second)">Shown inline near competition navigation only when selected or evaluated answers would be cleared.</div>' +
        '</div>' +
      '</div>' +
      '</div>'
    ));

    const q = (s) => kit.stage.querySelector(s);
    this.scrim = q('.mobile-drawer-scrim');
    this.panel = q('.mobile-drawer-panel');

    this.cur = kit.cursor();
    this.cur.keys = [
      { t: 0.3, at: [620, 420] },
      { t: 0.85, at: [442, 190] },
      { t: 2.95, at: [442, 190] },
      { t: 3.7, at: [620, 420] }
    ];
    this.cur.clicks = [0.95, 3.05];
    this.cur.visible = (t) => seg(t, 0.15, 0.35) * (1 - seg(t, 4.0, 4.3));
  },
  render(t) {
    const open = eo(seg(t, 1.05, 1.45));
    const close = ei(seg(t, 3.15, 3.5));
    const amt = Math.max(0, open - close);

    this.scrim.style.opacity = amt;
    this.panel.style.transform = 'translateX(' + lerp(-312, 0, amt).toFixed(1) + 'px)';

    this.cur.render(t);
  }
});
